import java.util.*;

class Solution {
  private List<Integer>[] g;
  private int k, count;
  private int[] values;

  private long dfs(int u, int parent) {
    long sum = values[u];
    for (int v : g[u]) if (v != parent) sum += dfs(v, u);
    if (sum % k == 0) {
      count++;
      return 0;
    }
    return sum % k;
  }

  public int maxKDivisibleComponents(int n, int[][] edges, int[] values, int k) {
    this.k = k;
    this.values = values;
    count = 0;
    g = new List[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    dfs(0, -1);
    return count;
  }
}
